    a_intervals = sorted([interval for interval in a if interval[0] < interval[1]])
    b_intervals = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_intervals:
        return []

    if not b_intervals:
        return a_intervals

    # Merge overlapping/touching intervals in a
    merged_a = []
    for start, end in a_intervals:
        if merged_a and merged_a[-1][1] >= start:
            merged_a[-1][1] = max(merged_a[-1][1], end)
        else:
            merged_a.append([start, end])

    # Merge overlapping/touching intervals in b
    merged_b = []
    for start, end in b_intervals:
        if merged_b and merged_b[-1][1] >= start:
            merged_b[-1][1] = max(merged_b[-1][1], end)
        else:
            merged_b.append([start, end])

    result = []

    # For each interval in merged_a, subtract all intervals in merged_b
    for a_start, a_end in merged_a:
        current_intervals = [[a_start, a_end]]

        for b_start, b_end in merged_b:
            new_intervals = []
            for c_start, c_end in current_intervals:
                # No overlap
                if c_end <= b_start or c_start >= b_end:
                    new_intervals.append([c_start, c_end])
                else:
                    # There is overlap, keep the parts that don't overlap
                    if c_start < b_start:
                        new_intervals.append([c_start, b_start])
                    if c_end > b_end:
                        new_intervals.append([b_end, c_end])
            current_intervals = new_intervals

        result.extend(current_intervals)

    # Merge touching/overlapping intervals in result
    if not result:
        return []

    result.sort()
    final = []
    for start, end in result:
        if final and final[-1][1] >= start:
            final[-1][1] = max(final[-1][1], end)
        else:
            final.append([start, end])

    return final

